/* Advanced1 — constructive review, evidence and workload trade-offs. */
(function(){
 const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x)),R='us-east-1',A='123456789012',NAME='shop-review',BUCKET='wa-audit';
 const TRAIL=`arn:aws:cloudtrail:${R}:${A}:trail/${NAME}`,ALB=`arn:aws:elasticloadbalancing:${R}:${A}:loadbalancer/app/shop-review/0000000000000021`,TOPIC=`arn:aws:sns:${R}:${A}:review-alerts`;
 const canonical=(v,key='')=>{if(['Action','Resource','aws:SourceArn','s3:x-amz-acl','Service'].includes(key)&&(typeof v==='string'||Array.isArray(v)&&v.every(x=>typeof x==='string')))return (Array.isArray(v)?v:[v]).slice().sort();if(Array.isArray(v)){const a=v.map(x=>canonical(x));if(a.every(x=>x&&typeof x.Sid==='string'))a.sort((a,b)=>a.Sid.localeCompare(b.Sid));return a;}return v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k],k)])):v;};
 const same=(a,b)=>JSON.stringify(canonical(a))===JSON.stringify(canonical(b));
 const POLICY={Version:'2012-10-17',Statement:[{Sid:'ACL',Effect:'Allow',Principal:{Service:'cloudtrail.amazonaws.com'},Action:'s3:GetBucketAcl',Resource:'arn:aws:s3:::'+BUCKET,Condition:{StringEquals:{'aws:SourceArn':TRAIL}}},{Sid:'Write',Effect:'Allow',Principal:{Service:'cloudtrail.amazonaws.com'},Action:'s3:PutObject',Resource:`arn:aws:s3:::${BUCKET}/AWSLogs/${A}/*`,Condition:{StringEquals:{'s3:x-amz-acl':'bucket-owner-full-control','aws:SourceArn':TRAIL}}}]};
 const SELECTORS=[{ReadWriteType:'All',IncludeManagementEvents:true,DataResources:[]}];
 const ALARM={AlarmName:'review-5xx',Namespace:'AWS/ApplicationELB',MetricName:'HTTPCode_Target_5XX_Count',Dimensions:[{Name:'LoadBalancer',Value:'app/shop-review/0000000000000021'}],Statistic:'Sum',Unit:'Count',Threshold:5,ComparisonOperator:'GreaterThanThreshold',Period:60,EvaluationPeriods:2,DatapointsToAlarm:2,TreatMissingData:'missing',ActionsEnabled:true,AlarmActions:[TOPIC]};
 const Q=(q,correct,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};};
 const files={'trail-policy.json':{desc:'Exact CloudTrail service/account path, trail SourceArn ke saath; bucket ka saboot bachao',content:JSON.stringify(POLICY,null,2)},'management.json':{desc:'Read aur write management events; is fixture mein alag bill hone wala data-event selector nahi',content:JSON.stringify(SELECTORS,null,2)},'5xx-alarm.json':{desc:'Review kiya component diagnostic alarm; Count/Sum, 2×60s mein se 2; customer error-rate SLO nahi',content:JSON.stringify(ALARM,null,2)},'review.txt':{desc:'Fictional review ka scope, owners aur baaki runtime kaam',content:'ShopKaro: 40 engineers/3 teams, checkout workload. Teen bataye config risks: DB HA/backups; review kiya 5xx alarm; scoped multi-Region management trail ki logging/validation. Config theek karo, phir runtime ka kaam rakho: restore aur business-ID milaan, asli SLO aur alarm delivery, S3 logs/digests aur validation. Zero bataye config findings AWS WA assessment ya certificate nahi.'}};
 function seed(interview=false){return {region:R,now:'2026-10-27T12:00:00Z',callerIdentity:{Account:A,UserId:'TRAINING',Arn:`arn:aws:iam::${A}:role/review-operator`},rds:[{id:'orders',resourceId:'db-original-review-orders',name:'orders',engine:'postgres',class:'db.t3.medium',state:'available',multiAZ:interview,backupRetention:interview?7:0,encrypted:true,publicAccess:false,deletionProtection:true,storage:100,dataFixture:[{orderId:'accepted101',total:499}]}],buckets:[{name:BUCKET,bucketId:'original-review-evidence',region:R,public:false,bpa:{BlockPublicAcls:true,IgnorePublicAcls:true,BlockPublicPolicy:true,RestrictPublicBuckets:true},objects:[{key:'original.txt',body:'TEST original review evidence',size:29}],...(interview?{policy:clone(POLICY)}:{})}],elbs:[{id:ALB,arn:ALB,name:'shop-review',fixtureId:'original-review-alb',type:'application',scheme:'internet-facing'}],topics:[{name:'review-alerts',arn:TOPIC,topicId:'original-review-topic',attributes:{FifoTopic:'false'},subscriptions:[]}],alarms:interview?[{name:'review-5xx',alarmId:'original-review-alarm',revision:1,definition:clone(ALARM),state:'ALARM'}]:[],trails:interview?[{name:NAME,arn:TRAIL,homeRegion:R,trailId:'original-review-trail',revision:1,bucket:BUCKET,multi:false,global:false,validation:false,logging:false,selectors:[{ReadWriteType:'WriteOnly',IncludeManagementEvents:false,DataResources:[]}]}]:[],managementEvents:[{EventId:'training-change101',EventName:'ModifyDBInstance',EventSource:'rds.amazonaws.com',EventTime:'2026-10-26T11:00:00Z',Username:'course-operator',ReadOnly:'false',Resources:[{ResourceType:'AWS::RDS::DBInstance',ResourceName:'orders'}],CloudTrailEvent:'{"training":true,"reason":"console change without review"}'}],capacityMetrics:[{seriesId:'original-review-errors',version:1,period:60,namespace:'AWS/ApplicationELB',metric:'HTTPCode_Target_5XX_Count',unit:'Count',dimensions:clone(ALARM.Dimensions),points:[{Timestamp:'2026-10-27T11:58:30Z',SampleCount:1200,Sum:8},{Timestamp:'2026-10-27T11:59:30Z',SampleCount:1200,Sum:9}]}]};}
 const initial=seed(),db=s=>s.account.rds.find(r=>r.id==='orders');
 function preserved(s){const a=s.account,b=a.buckets.find(b=>b.name===BUCKET),d=db(s);return a.rds.length===1&&d?.resourceId==='db-original-review-orders'&&d.engine==='postgres'&&d.class==='db.t3.medium'&&d.storage===100&&d.encrypted&&!d.publicAccess&&d.deletionProtection&&same(d.dataFixture,initial.rds[0].dataFixture)&&a.buckets.length===1&&b?.bucketId==='original-review-evidence'&&!b.public&&same(b.bpa,initial.buckets[0].bpa)&&b.objects.length===1&&b.objects[0].key==='original.txt'&&b.objects[0].body==='TEST original review evidence'&&same(a.elbs,initial.elbs)&&a.topics.length===1&&a.topics[0].topicId==='original-review-topic'&&a.topics[0].arn===TOPIC&&same(a.managementEvents,initial.managementEvents);}
 const database=s=>db(s)?.state==='available'&&db(s).multiAZ&&db(s).backupRetention>=7;
 function alarm(s){const a=s.account.alarms.find(a=>a.name==='review-5xx'),snap=a&&AG.capacityAlarmSnapshot(s.account,a);return s.account.alarms.length===1&&!!a&&same(a.definition,ALARM)&&snap.state==='ALARM'&&snap.source==='fixture-metrics'&&snap.seriesId==='original-review-errors'&&snap.version===1&&snap.points.length===2&&(s.account.capacityAlarmReads||[]).some(r=>r.alarmId===a.alarmId&&r.revision===a.revision&&r.source===snap.source&&r.state===snap.state&&r.seriesId===snap.seriesId&&r.version===snap.version&&same(r.view,a.definition));}
 function trail(s,interview=false){const t=s.account.trails.find(t=>t.name===NAME),b=s.account.buckets.find(b=>b.name===BUCKET);return s.account.trails.length===1&&!!t&&(!interview||t.trailId==='original-review-trail')&&t.arn===TRAIL&&t.homeRegion===R&&t.bucket===BUCKET&&!t.prefix&&t.multi&&t.global&&t.validation&&t.logging&&same(t.selectors,SELECTORS)&&same(b?.policy,POLICY)&&AG.auditTrailAccess(s.account,t)&&(s.account.trailReads||[]).some(r=>r.trailId===t.trailId&&r.revision===t.revision&&r.destinationAllowed&&same(r.view,t));}
 const solution=['aws s3api put-bucket-policy --bucket wa-audit --policy file://trail-policy.json','aws rds modify-db-instance --db-instance-identifier orders --multi-az --backup-retention-period 7 --apply-immediately','aws rds wait db-instance-available --db-instance-identifier orders','aws cloudwatch put-metric-alarm --cli-input-json file://5xx-alarm.json','aws cloudwatch describe-alarms --alarm-names review-5xx','aws cloudtrail create-trail --name shop-review --s3-bucket-name wa-audit --is-multi-region-trail --include-global-service-events --enable-log-file-validation','aws cloudtrail start-logging --name shop-review','aws cloudtrail get-trail-status --name shop-review'];
 const tasks=[{text:'Purane orders, private saboot ka bucket, ALB/topic aur pehle se daale events bache rahe',check:preserved},{text:'Purana DB available, Multi-AZ aur ≥7 din backups ke saath; restore ka daava nahi',check:database},{text:'Review kiya Count/Sum 5xx alarm, diye periods ka taaza ALARM read; asli SLO ka daava nahi',check:alarm},{text:'Scoped multi-Region/global management trail: logging + validation ka config aur aaj ka status read',check:s=>trail(s)}];
 const isolution=['aws cloudtrail update-trail --name shop-review --is-multi-region-trail --include-global-service-events --enable-log-file-validation','aws cloudtrail put-event-selectors --trail-name shop-review --event-selectors file://management.json','aws cloudtrail start-logging --name shop-review','aws cloudtrail get-trail-status --name shop-review'];
 const itasks=[{text:'Purana saboot/orders/ALB/topic/events bache; DB HA/backups set hi rahe',check:s=>preserved(s)&&database(s)&&s.account.alarms.length===1&&same(s.account.alarms[0].definition,ALARM)},{text:'Purana trail theek: All management, flags, logging aur aaj ka status; purana backfill ya delivery ka daava nahi',check:s=>trail(s,true)}];
 function plan(k){const p=[{rps:350,cpu:1,rate:.18},{rps:500,cpu:2,rate:.25},{rps:650,cpu:4,rate:.40}][k.size],days=[1,7,14][k.backups],retention=[7,30,90][k.logs],spot=[0,.25,.5][k.spot],onDemand=12-Math.floor(12*spot),survivors=onDemand-Math.ceil(onDemand/3),capacity=survivors*p.rps*.7,db=400+1200*(k.cache?.2:1)+(k.edge?0:200),cost=12*100*p.rate*(1-.75*spot)+(k.ha?240:120)+days*2+k.cache*35+k.edge*15+retention*.4,cpu=12*100*p.cpu,risks=[!k.ha||days<7,capacity<2000,db>800,retention<30].filter(Boolean).length;return {days,retention,capacity,db,cost,cpu,risks,ok:risks===0&&cost<=650&&cpu<=3000};}
 AG.registerLevels('advanced',[{
  id:'wellarch',icon:'🏛️',title:'Well-Architected: saboot aur trade-offs',badge:'Pillar Pandit',
  objectives:['Chhe pillars ko business ke risks/saboot se jodna','Scope/lens, HRI/MRI improvement plan aur milestones samjhana','Kharcha, failure budget aur resources ke sahi use ke trade-offs nikaalna','Asli data bachate hue teen bataye config risks theek karna'],
  hook:{when:'ShopKaro course ki kahani (fictional)',title:'Series A review: 40 engineers, 3 teams, budget kam',text:'Mahasale ke baad Neha ke paas chamakdaar architecture diagram hai, par chaar incidents ka saboot bikhra hua hai. Database restore kab test hua? Console mein badlav kisne kiya? Alert ka owner kaun? Ravi har service jodna chahta hai; reviewer business ka asar aur check kiya sudhaar poochta hai.',mission:'Chhe pillars se kaam ka review karo, sabse zaroori risks pehle rakho aur sabse chhota, sahi saabit hone wala improvement plan likho. Course scanner 3 config contracts check karta hai; yeh poora AWS WA assessment, certificate ya launch ki manzoori nahi.'},
  steps:[
   {q:'Framework review ka result services ki checklist kyun nahi?',analogy:'Restaurant ki inspection mein menu, khane ki safety, staff aur delivery ke vaadon par baat hoti hai. Naya oven khareedna safai ke missing record ka jawaab nahi.',body:'<p>Workload components ka ek set hai jo business ko value deta hai. Lens chunne se pehle checkout ki boundary, customers, accounts/Regions, dependencies, owner aur business goals tay karo. AWS review ko ek kaam ki baatcheet batata hai, audit ya certificate nahi.</p>',points:['Chhe sawaal: Operational Excellence → chalana/sudhaarna? Security → bachana/access/pakadna? Reliability → wapas chalu hona aur demand poori karna? Performance Efficiency → sahi resources? Cost Optimization → har kharche par business ki value? Sustainability → resources ki barbaadi/mahaul par asar?','Chhota scope: ShopKaro checkout orders leta hai; bahar ke payment/email dependencies ke owners aur failure contracts hain. Marketing site ke metrics checkout ke results ki jagah nahi le sakte.','Hands-on: dry run mein har component par saboot ka sawaal jawaab do. Expected: ek risk + owner/test, koi har jagah lagu production stack nahi.'],asli:'Jaldi review karo, bade badlav/milestones par aur incidents ke baad. Ek lagatar cadence chuno; har teen mahine ek example hai, AWS ka zaroori schedule nahi.'},
   {q:'Chhe pillars ke principles kaam mein kaise dikhte hain?',analogy:'Restaurant ki SOP, taale, backup stove, sahi oven, portion ka budget aur khane ki barbaadi aapas mein jude hain; par har chinta ka mukhya sawaal alag hai.',body:'<p>Operations: chhote, wapas liye ja sakne wale badlav, observability aur seekhna. Security: identity ka pakka base, sabse kam permission, layers aur traceability. Reliability: limit wali capacity, jahan theek ho wahan apne aap recovery, aur test ki hui recovery. Performance: resources ke chunav naapo, try karo aur sahi managed services use karo. Cost: business output/kharcha naapo aur barbaadi hatao. Sustainability: asar samjho, resources ka kaam ka use badhao aur bekaar kaam kam karo.</p>',points:['Overlap aam baat hai: versioned IaC operations aur recovery dono sudhaarta hai; encryption security, kharche aur performance par asar daalta hai. Dikhi problem se mukhya pillar chuno, phir baaki asar bhi likho.','Galti jo sab karte hain: har Auto Scaling/CDN item ko Reliability mein daalna. Agar goal naape response time ke liye resources chunna hai, toh mukhya chinta Performance Efficiency hai.','Hands-on: chhe-bin game mein chhe pillars hain. Expected explanations bataye goal ka naam leti hain aur overlap bhi maanti hain.'],asli:'Pillar ka label shuru ka sawaal hai; sirf service ka naam asli wajah nahi pehchanta, na risk band karta hai.'},
   {q:'Risk ko budget ke saamne kaise prioritize karein?',analogy:'Leak karti gas line aur mehenga tablecloth, dono issues hain; par business ka asar, jaldi aur theek karne ki mehnat barabar nahi.',body:'<p>AWS WA Tool jawaab aur high/medium risk issues ek improvement plan ke saath rakhta hai. Asar, sambhavna/khule hone ka darja, dependencies, mehnat, owner aur check tay karo. Course scanner kuch fields check kar sakta hai; scanner ki findings saaf bataye contracts hain, official HRI/MRI ratings nahi.</p>',points:['Maana hua quote: single-AZ DB $120/mahina vs Multi-AZ $240/mahina, baaki meters ke bina. $120/mahina ka farak bataye AZ-HA risk ko sambhal sakta hai, par test ki hui regional recovery ya fixed availability % nahi khareedta.','Kharcha vs risk: cache eligible reads ka load kam karta hai par purana data aur chalane ka kaam jodta hai. Spot ki chhoot sirf interrupt ho sakne wali capacity par hai; zaroori serving ko kaafi On-Demand base aur review ki recovery se bachao. Managed services ko bhi boundaries, quotas aur owner chahiye.','Galti jo sab karte hain: shartein dekhe bina sabse sasta option, ya business ka kaam delete karke sabse sasta dikhne wala graph. Pehle shartein poori karne wale options compare karo, phir har kaam ke output ka kharcha.'],asli:'Risk maanne ke liye saaf, allowed owner, expiry aur bachav ke controls chahiye. Risk chhupane ke liye jawaab badalna ilaaj nahi.'},
   {q:'WA Tool, lenses aur milestones ka workflow kya hai?',analogy:'Health record mein mareez, specialist ka nazariya, saboot aur agli visit hoti hai. Har mareez ke liye ek hi questionnaire poori jaanch nahi.',body:'<p>Workload/review owner/environment/Regions tay karo. Framework lens apne aap lagta hai; Lens Catalog ya custom lenses mein se jo lagu ho woh chuno. Har lens ke apne sawaal, best practices, notes aur improvement plan hote hain. Aaj ke examples mein Serverless Applications Lens aur SaaS Lens hain; lagu hona/version check karo, "50 sawaal" jaisa fixed vaada nahi.</p>',points:['Jawaab dene se pehle source/saboot padho. Shuru ka milestone save karo, improvement items prioritize karo, lagao/test karo, phir naya milestone save karo. Milestones ek time ki state rakhte hain; jawaab badalne se deployment nahi chalta.','Tool ka koi extra charge nahi; sudhaar ke liye lage resources/tests ka bill ho sakta hai. Local lab AWS WA Tool nahi chalata, na official risk report banata hai.','Hands-on: optional, approved asli-AWS exercise: Workloads → Define workload → scope/owner → lagu lenses chuno → saboot/notes review karo → milestone save karo. Expected result: likha hua baseline aur improvement plan.'],asli:'Chune lens ke asli sawaal use karo; ginti aur content badalte rehte hain. Workload aur uski business dependencies review karo, ratte hue sawaalon ki ginti nahi.'},
   {q:'Backup retention aur wapas aaye business state mein kitna farak hai?',analogy:'Restaurant ke fridge mein extra saamaan hona pakka khana pahunchne ka saboot nahi. Recovery ki recipe aur asli practice chahiye.',body:'<p>Multi-AZ HA, backups/PITR, replicas aur regional DR alag failures sambhalte hain. RPO = kitna data loss manzoor hai; RTO = wapas chalu hone ka kitna time manzoor hai. Recovery mein permissions/keys, networking, app config, dependencies aur business ka milaan aata hai. Sirf snapshot ya Available status yeh results nahi dikhata.</p>',points:['Example contract: nayi alag target mein restore karo, accept hue order IDs/totals aur app ka behaviour check karo, asli data point/time aur recovery ka time likho. Production source aur saboot sahi-salaamat rakho.','Galti jo sab karte hain: 7 din ki backup retention ko RPO 7 din ya RTO 7 minute bolna. Retention batata hai recovery history kitni der rakhte hain; capture ka gap/latest restore point aur naapi recovery asli recovery ka saboot tay karte hain.','Production mein aisa hota hai: key ki permission, missing secret, purana endpoint ya bina test ka restore process recovery rok deta hai, chahe backup available dikhe. Approved alag jagah par failure modes/quotas ki practice karo.','Hands-on: terminal HA/backups theek karta hai aur config ke available hone ka wait karta hai. Expected: purane orders bache. Local mein SQL restore/failover ya RTO/RPO ka naap ka daava nahi.'],asli:'Config badalne ke baad bhi recovery test aur milaan naam wale improvement items rehte hain; do flags se poora reliability review band mat karo.'},
   {q:'DB kisne badla? CloudTrail aur alarms alag saboot kyun hain?',analogy:'Cash register ka audit batata hai ki daam kisne badla. Line ka meter abhi ki der dikhata hai. Aaj recorder on karne se pichhle mahine ki missing recording wapas nahi aati.',body:'<p>CloudWatch metrics/logs/traces operations ke sawaalon ke jawaab dete hain; CloudTrail supported account/API activity record karta hai. Event history chune Region mein pichhle 90 din ke management events deta hai, naye trail se alag. Trails aage ki chuni delivery set karte hain; S3/object data events ke liye alag review kiye selectors/kharcha chahiye. Multi-Region trail on Regions ko cover karta hai, har mumkin operation ko nahi.</p>',points:['CloudTrail destination ko chalne layak S3 policy chahiye: account ke AWSLogs path par GetBucketAcl aur PutObject, review kiya SourceArn aur bucket-owner-full-control ki shart. Multi-Region/global flags, management selector, logging status aur destination ka saboot alag checks hain.','Log-file validation on karne se aage signed digest delivery ho sakti hai; asli integrity validation ek alag action hai. IsLogging=true, aur Moto ka nakli LatestDeliveryTime bhi, pahunchi files ya check hue digests prove nahi karte.','Hands-on: app mein lookup-events pehle se daala TRAINING badlav dikhata hai. Lab21 mein asli LookupEvents support nahi (500); Moto bucket policy na hone par bhi maan leta hai aur delivery status nakli banata hai. Dono kamiyan saaf likhi hain.','Production mein aisa hota hai: galat bucket/KMS/selector scope se gaps bante hain, jabki control-plane config bana hota hai. Pahunche logs/digests, aaj ke errors/permissions aur asli alarm actions check karo; purana saboot bachao.'],asli:'Alarm ek component ka symptom pakadta hai; Event history management ka badlav samjha sakti hai. Dono se har business result ya poora security review saabit nahi hota.'},
   {q:'Cost Optimization aur Sustainability ek hi score hain?',analogy:'Chhoot wala bijli ka bill aur kam barbaad khana alag results hain. Sasta rate milne par bhi rasoi poori raat chal sakti hai.',body:'<p>Har safal order ka kharcha aur har kaam ke output par resources ka use, dono track karo. Sahi size do, khaali kaam/data hatao, aur code, storage aur access patterns sudhaaro. Commitment/Spot ki chhoot daam kam karti hai, resource-hours zaroori nahi. Graviton jaisa architecture/CPU badlav compatibility aur asli jaise benchmarks maangta hai.</p>',points:['Course board maanta hai: 12 workers × 100 active ghante/mahina. Profile M 2 vCPU use karta hai → 2400 app vCPU-ghante/mahina. 25% Spot model ka daam kam kar sakta hai, par wahi 2400 resource-ghante rehte hain. Yeh energy/carbon ka andaaza nahi.','Region ke chunav mein latency, data residency, service availability aur recovery ki zarooratein mahaul ke goals ke saath poori honi chahiye; "sabse green Region" ka koi ek pakka jawaab nahi. Resources ki ginti kam dikhane ke liye zaroori redundancy mat chhodo.','Galti jo sab karte hain: bina naape "safety ke liye" sabse bada instance lena, ya chhoot ko naapa hua carbon ghatna bolna. Throughput/tails, utilization aur kul kaam ka kaam check karo.','Hands-on: planner saaf fictional component quotes, AZ jaane ke baad Spot se alag zaroori capacity, model ka DB dabaav aur app ke resource-hours dikhata hai. Asli uptime/p95/security score ka andaaza nahi lagaya jaata.'],asli:'Board bataye maani baaton ke saath faisle ko chhota karta hai. Production sizing, mahaul par asar aur customer SLO ke liye asli saboot aur zyada meters chahiye.'},
   {q:'ADR aur improvement ticket mein exactly kya likhein?',analogy:'Restaurant ka menu badlne ka note likhta hai ki dish kyun badli, kaun test karega, kya asar ummeed hai aur wapas kaise karein. Naye saamaan ki receipt safalta ki report nahi.',body:'<p>Chhota ADR likho: context/zaroorat → options → chuna trade-off → result/bacha risk → owner → check/rollback ka trigger. Improvement item ko priority, due date aur manzoori ka saboot bhi chahiye. Jab maani baatein, dependencies badlein ya bade incidents hon, toh dobara review karo.</p>',points:['Chhota ADR: AZ jaane wala goal maane hue $120/mahina ke DB farak se zyada zaroori hai. Multi-AZ/backups on karo, source bachao, approved sandbox mein restore test karo; regional DR ka daava nahi. Owner: Ravi; safalta: likha hua config + alag se naapi aur milaai gayi recovery.','Galti jo sab karte hain: scanner ki 0 findings = saare chhe pillars pass. Local scanner sirf 3 bataye config contracts check karta hai; identity, deployment, performance, sustainability aur runtime ke results ka review phir bhi chahiye.','Hands-on: terminal poora karo, phir manzoori ka ek statement likho jo check hua config aur ek na check hua runtime item ka naam le. Expected: na nakli certificate, na kisi company ka banaya incident, na apne aap business launch ki manzoori.'],asli:'Kaam ka review samay ke saath faisle aur saboot behtar karta hai. Report ko bachi anjaani baatein agle owner ke liye saaf dikhani chahiye.'}
  ],
  myth:[{myth:'Poora WA questionnaire production availability ka certificate hai.',sach:'Review jawaab, saboot aur sudhaar rakhta hai; yeh runtime test, compliance certificate ya pakka SLO nahi.'},{myth:'Sabse sasta option hi sahi architecture hai.',sach:'Pehle business, security/recovery aur performance ki shartein poori karo; phir sahi options mein kharcha compare karo.'},{myth:'Backup 7 din matlab RTO 7 minute aur RPO 7 din.',sach:'Retention, capture/recovery point aur naapa recovery time alag cheezein hain; practice karo aur milaan karo.'},{myth:'Chhoot se mahaul par kam asar prove hota hai.',sach:'Daam badalne se resources ka use kam hona zaroori nahi. Kaam ke output/resource ka asar naapo; zaroori resilience bachao.'}],
  playbook:{title:'Review se check kiye sudhaar tak',use:['Bade design/launch badlav se pehle, incidents ke baad aur workload ke hisaab se cadence par.','Jab teams ki raay alag ho: service chunne se pehle business ki shart aur saboot tay karo.','Limit wale improvement backlog ke liye, owners, check aur bache risk ke saath.'],avoid:['Fixed sawaalon ki ginti, ya ek baar ke certificate wali soch.','Jawaab badal kar ya saboot/business kaam delete karke risks chhupana.','Kuch config knobs se banaye uptime/security/carbon scores.'],how:['Workload, dependencies aur business SLO/RTO/RPO ka scope tay karo.','Lagu lens chuno; config, runtime aur business ka saboot ikattha karo.','Asar/mehnat/dependencies se risks prioritize karo, owners aur expiry ke saath.','Chhota test kiya badlav lagao, vaada ki gayi boundary check karo, milestone/ADR likho aur dobara dekho.'],redflags:['Backup hai par restore/milaan ka saboot nahi.','Alarm/trail ka naam hai par unit/dimension/permission/selector/delivery missing.','Kharcha girta hai par resource-hours, failures ya khoya kaam badhta hai.'],rule:'Customer ka kaunsa result fail ho sakta hai, risk ka saboot kya hai, aur owner ke saath sabse chhota test kiya sudhaar kya hai?'},
  exam:[{cue:'Poore workload ka review',pick:'Chhe pillars + zarooratein; kaam ki baatcheet'},{cue:'Selected lens questions',pick:'Scope/version ke hisaab se; "50 sawaal" jaisa fixed niyam nahi'},{cue:'HRI/MRI',pick:'Prioritize kiya improvement plan + owner/saboot'},{cue:'Milestone',pick:'Ek time ki review state; deployment nahi'},{cue:'Backup retention vs recovery',pick:'RTO/RPO ke liye naapa restore aur milaan chahiye'},{cue:'Who changed a resource?',pick:'CloudTrail management history; Region/90 din ka scope'},{cue:'Logging aur validation flags',pick:'Pehle config; pahunche logs/digests aur validation alag'},{cue:'Cheapest suitable design',pick:'Kharcha kam karne se pehle shartein poori karo'},{cue:'Sustainability versus discount',pick:'Resource/kaam ke output ka saboot, sirf daam nahi'}],
  lesson:['<h3>Kab kya: saboot compare karo</h3><div class="tbl-wrap"><table class="review-table"><tr><th>Zaroorat</th><th>Kya use karein</th><th>Limit</th></tr><tr><td>Workload ke trade-offs</td><td>WA Framework/Tool + lagu lens</td><td>Jawaab/notes tests nahi chalate</td></tr><tr><td>Ek time ka review</td><td>Milestone + improvement plan</td><td>Naya milestone deployment nahi</td></tr><tr><td>Component ka abhi ka symptom</td><td>Metrics/logs/traces + alarms</td><td>Sahi unit/dimension/freshness</td></tr><tr><td>Management ka badlav</td><td>CloudTrail Event history/trail</td><td>Region/window/selectors/delivery</td></tr><tr><td>Recovery ka vaada</td><td>Restore/failure drill + business milaan</td><td>Config ka available hona kaafi nahi</td></tr><tr><td>Efficiency ka goal</td><td>Har resource aur kharche par kaam ka output</td><td>Sirf chhoot resources ka ghatna nahi</td></tr></table></div><p>Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p><p><b>Faisla kaise karein:</b> customer ki shart saaf nahi? Pehle scope/SLO/recovery tay karo. Shart saaf hai? Missing saboot dhoondho → mukhya pillar aur overlaps pehchano → asar/mehnat se prioritize karo → sabse chhota, wapas liya ja sakne wala sudhaar chuno. Config badla? Config check karo, phir asli runtime/business result. Maani baat badli? Dobara review karo aur milestone/ADR likho.</p>'],
  stages:[
   {type:'dryrun',title:'🧪 Workload ka review karo, sirf boxes ka nahi',intro:'Fictional ShopKaro review. "Agla" click karo; woh saboot chuno jo bataye business sawaal ka jawaab de.',lesson:'Pillar ek sawaal pehchanta hai; sudhaar ko scope, owner, config ka saboot aur sahi runtime/business test chahiye.',nodes:[N('app',150,150,{label:'Checkout scope'}),N('alb',470,150,{label:'Tail / errors'}),N('rds',790,150,{label:'Orders recovery'}),N('s3',790,420,{label:'Audit evidence'}),N('cw',470,420,{label:'Review plan'})],edges:[{from:'app',to:'alb'},{from:'alb',to:'rds'},{from:'rds',to:'s3'},{from:'s3',to:'cw'}],panels:[{id:'risk',title:'Declared risk / owner'},{id:'proof',title:'Check hui boundary / bacha test'}],steps:[
    {say:'Diagram review karne se pehle checkout aur uske payment/email dependencies tay karo. Marketing ki availability checkout ki availability nahi.',panels:{risk:['Owner: Neha; accept hue orders ka sahi hona/SLO zaroori','Aaj ka lens aur scope review karo'],proof:['Config, runtime aur business ka saboot ikattha karo']}},
    {say:'ALB ka naam hai, par koi sahi 5xx alarm set nahi. Operations mein pakadne ki kami ek bataya course risk hai.',panels:{risk:['Operational Excellence: review kiya detection missing','Owner: Ravi; exact unit/dimension/period/actions'],proof:['Alarm banana sirf config hai','Asli signal/action ke raaste ko runtime test chahiye']},ask:Q('Naya bana alarm OK kehta hai par taaze samples nahi. Review kya result nikaal sakta hai?', 'Config ban gaya hoga; health bolne se pehle dimensions, samples ki freshness aur asli notification delivery dekho',['OK customer SLO band karne ke liye kaafi hai, kyunki config banane mein poora live load test bhi hota hai','Koi bhi alarm ka naam monitoring coverage saabit karta hai, isliye reviewer metric aur destination ki details chhod sakta hai','Haath ka OK override taaza metric data deta hai, isliye missing production naap ki jagah le leta hai'],0,'Save hua alarm customer ka naapa result nahi. No-data/initial/haath ki state bhatka sakti hai; sirf naam se unit, dimensions, signal aur delivery ka scope chhoot jaata hai.')},
    {say:'Orders Single-AZ hai aur 0 din backup. Bataya HA/history contract set karo, phir order-ID milaan ke saath alag restore ki planning karo.',panels:{risk:['Reliability: HA/backups ka config nahi','Owner: Ravi; recovery drill abhi bhi chahiye'],proof:['Available + MultiAZ + 7 din sirf config hai','Retention se RTO/RPO ka andaaza nahi']},ask:Q('Backup retention 7 din hone ke baad, recovery ke vaade ke liye kaunsa saboot abhi bhi chahiye?', 'Approved environment mein restore karo aur accept hue business IDs milao, asli recovery point aur beeta time likho',['7 din retention ko 7 minute ka RTO maano, kyunki managed database service mein unit badalna pehle se bana hai','Ek baar Available padho, kyunki instance ka available hona har restore hue app dependency ko apne aap login kara deta hai','Ek async reader jodo aur RPO zero bolo, kyunki reader endpoint har commit hue order ke current hone ka saboot hai'],1,'Retention history ki lambai hai, naapa recovery time/data loss nahi. Available dependencies test nahi karta; async replication zero lag ya business milaan ki guarantee nahi deti.')},
    {say:'CloudTrail logging band hai. Destination policy, on Regions ka coverage, management selector aur aage ke digest config review karo. Asli S3 saboot bachao.',panels:{risk:['Security: scoped lagatar audit config nahi','Owner: security operator; destination/runtime check karo'],proof:['Trail banane se purana backfill nahi hota','Event history ek alag Region/90 din ka view hai']}},
    {say:'Budget board bataye component quotes aur zaroori On-Demand capacity compare karta hai. Spot ki chhoot kharcha kam kar sakti hai jabki resource-hours waise hi rehte hain.',panels:{risk:['Cost + Sustainability: alag goals','Zaroori resilience aur kaam ka kaam bachao'],proof:['Koi nikaala hua uptime/security/carbon score nahi','Asli jaise benchmarks chahiye']},ask:Q('Workers, vCPU aur runtime same; sirf Spot ka daam badla. Kya result nikalta hai?', 'Model ka daam gir sakta hai jabki resource-hours same rahein; mahaul par asar ke liye chhoot se zyada saboot chahiye',['Chhoot ka percentage hi carbon ka ghatna hai, kyunki billing ke badlav processor cycles seedhe hata dete hain','Zaroori serving ki resilience apne aap same rehti hai, kyunki kam daam har Spot interruption rok deta hai','Sirf chhota bill har resource-ghante par zyada kaam prove karta hai, chahe poore orders ki ginti missing ho'],2,'Rate badalne se resources ka use ya kaam ka output badalna zaroori nahi. Spot interruptions ki planning phir bhi chahiye; bill ke size se carbon asar ya har business unit ki efficiency nahi nikalti.')},
    {say:'Config ke fixes, asli saboot aur baaki runtime ke kaam improvement plan mein likho. Bade progress ke baad naya milestone save karo; owner/expiry/rollback tay karo.',panels:{risk:['Teen bataye config items band ho sakte hain','Review ke baaki risks saaf scope ke saath bache rehte hain'],proof:['Review milestone ek time ka saboot hai','Na certificate, na apne aap launch ki manzoori']}}
   ]},
   {type:'flowlab',title:'🎛️ Trade-off board: chhoot se pehle shartein',goal:'Sabse bure AZ ke jaane par bhi, Spot par tike bina, 2000 requests/s ki zaroori service rakho; model ka DB ≤800 units/s; Multi-AZ + ≥7 din backup; logs ≥30 din; components ka kul quote ≤$650/mahina; app ≤3000 vCPU-ghante/mahina. Shuru: HA On, 7 din, cache On, Spot 25%, edge On, logs 30 din, profile M.',scenario:'Course ke fictional inputs, AWS ke daam ya EC2 benchmarks nahi: 12 workers, 3 barabar AZ, 100 active ghante/mahina; profiles S/M/L 70% allowance par 350/500/650 requests/s, 1/2/4 vCPU aur $0.18/$0.25/$0.40 har worker-ghanta. Spot par 75% chhoot maani, zaroori capacity mein kabhi pakki nahi gini. DB quote $120 single/$240 multi har mahina; backups $2 har rakhe din/mahina; cache $35/mahina; edge $15/mahina; logs $0.40 har rakhe din/mahina. Dabaav = 400 strong/write units/s + 1200 eligible reads/s × (cache On? 20% : 100%) + public files ka edge offload na ho toh 200. Sirf kharche/resources ka model; asli uptime, p95, security aur carbon naape nahi.',knobs:[{id:'ha',label:'Database HA configuration',min:0,max:1,step:1,value:0,labels:{0:'Single-AZ',1:'Multi-AZ'}},{id:'backups',label:'Backup retention',min:0,max:2,step:1,value:0,labels:{0:'1 day',1:'7 days',2:'14 days'}},{id:'cache',label:'Eligible read cache',min:0,max:1,step:1,value:0,labels:{0:'Off',1:'On (80% hit assumption)'}},{id:'spot',label:'Interruptible Spot share',min:0,max:2,step:1,value:2,labels:{0:'0%',1:'25%',2:'50%'}},{id:'edge',label:'Public files ka edge offload',min:0,max:1,step:1,value:0,labels:{0:'Off',1:'On'}},{id:'logs',label:'Zaroori audit retention scenario',min:0,max:2,step:1,value:0,labels:{0:'7 days',1:'30 days',2:'90 days'}},{id:'size',label:'Fictional worker profile',min:0,max:2,step:1,value:0,labels:{0:'S (1 vCPU)',1:'M (2 vCPU)',2:'L (4 vCPU)'}}],model:k=>{const p=plan(k);return {readouts:[{label:'AZ jaane ke baad zaroori capacity; Spot nahi gina',value:p.capacity.toFixed(0)+' requests/s'},{label:'Modeled DB pressure /800',value:p.db.toFixed(0)+' units/s'},{label:'Declared constraint failures',value:p.risks+' (not official HRIs)'},{label:'Fictional components ka kul quote',value:'$'+p.cost.toFixed(2)+'/month'},{label:'Sirf app ke resources ka use',value:p.cpu+' vCPU-h/month'},{label:'Runtime/customer evidence',value:'Uptime / p95 / carbon unmeasured'}],verdict:{ok:p.ok,text:p.ok?'Bataye budgets is fictional scenario mein fit hain. Asli recovery, performance aur business results alag check karo.':'Chhoot chunne se pehle zaroori capacity, DB, HA/history, retention, kharche aur resource-hour ki shartein dekho.'}};},check:k=>plan(k).ok,lesson:'Likha hua chunav: M, 25% Spot, HA, 7 din backups, cache + edge, 30 din logs → zaroori capacity 2100 requests/s; DB 640 units/s; kul $559.75/mahina; app 2400 vCPU-ghante/mahina. Spot ka daam kharcha kam karta hai par resource-hours 2400 hi rehte hain. Yeh maani baatein production SLO ka andaaza nahi lagati.'},
   {type:'bins',title:'Chhe pillars: mukhya sawaal chuno',instructions:'Item mein bataya mukhya focus chuno. Baaki pillars ko bhi fayda ho sakta hai; explanations overlap ka naam leti hain.',bins:[{id:'op',label:'Operational Excellence'},{id:'sec',label:'Security'},{id:'rel',label:'Reliability'},{id:'perf',label:'Performance Efficiency'},{id:'cost',label:'Cost Optimization'},{id:'sus',label:'Sustainability'}],items:[{text:'Ek chhota, wapas liya ja sakne wala deployment version karo aur uske runbook ki practice karo',bin:'op',explain:'Safe tarike se chalana/sudhaarna mukhya goal hai; reliability ko bhi fayda.'},{text:'Decrypt/audit permissions ka scope rakho aur sahi principal ka raasta check karo',bin:'sec',explain:'Allowed access/traceability bachana bataya security ka mudda hai.'},{text:'Alag DB restore karo aur recovery goals ke andar accept hue order IDs milao',bin:'rel',explain:'Naapi recovery aur business ki value ka chalte rehna reliability hai, sirf backup hona nahi.'},{text:'Asli jaisi response-time/throughput zarooraton ke saamne instances ka benchmark lo',bin:'perf',explain:'Naap se sahi resources chunna Performance Efficiency hai.'},{text:'Lagatar demand aur business kharcha naapne ke baad sahi commitment chuno',bin:'cost',explain:'Bataya goal kharcha/value hai, commitment/coverage ke risk ke review ke saath.'},{text:'Bekaar computations hatao aur har safal order par resources ka use track karo',bin:'sus',explain:'Har kaam ke output par barbaad resources kam karna bataya sustainability focus hai; kharcha bhi sudhar sakta hai.'}]},
   {type:'match',title:'Risk → mukhya pillar → saboot',instructions:'Har dikhi kami ko uske sabse seedhe sudhaar/saboot contract se jodo.',pairs:[{left:'Console mein baar-baar badlav, rollback ka owner saaf nahi',right:'Operations: versioned badlav, owner/runbook aur test kiya rollback',explain:'Dohraaya ja sakna, seekhna aur safe badlav ki zimmedari operations ki kami sambhalte hain.'},{left:'Scoped management audit ki delivery missing',right:'Security: trail permission/selector/config + pahunche logs ka validation',explain:'Config ek stage hai; asli logs/digests aur validation ka alag saboot chahiye.'},{left:'Backups hain par restore kabhi test nahi hua',right:'Reliability: RTO/RPO ke saamne alag restore aur business milaan',explain:'Backup object keys/network/dependencies ya asli recovery test nahi karta.'},{left:'Bina benchmark ka instance tail ka target chook jaata hai',right:'Performance: asli jaise workload ke experiments aur taaze tail metrics',explain:'Is mudde ko sahi resource/algorithm ka saboot chahiye, maana hua bada-instance wala ilaaj nahi.'},{left:'Khaali environment ka raat bhar bill',right:'Cost: schedule/ownership review karo aur zaroori service windows check karo',explain:'Khaali kharcha hatana madad karta hai; zaroori availability bachao aur asli bachat pakdo.'},{left:'Wahi kaam/resource-hours, sirf sasta rate',right:'Sustainability: asli resource/kaam ke output ka badlav alag naapo',explain:'Sirf chhoot daam badalti hai, physical/resource asar zaroori nahi.'}]},
   {type:'triage',title:'🩺 Chaar incident reports, ek gol-mol score',symptom:'Fictional teen-mahine ke notes: ek DB availability incident, ek fail restore rehearsal, ek bina review console badlav aur bina alarm ek customer error spike. Reviewer ko sahi saabit hone wala plan chahiye, ek pillar ka score nahi.',goal:'Saboot dekho, overlap wale risks pehchano aur pehle check kiye sudhaar saunpo.',commands:[{cmd:'aws cloudtrail lookup-events --lookup-attributes AttributeKey=EventName,AttributeValue=ModifyDBInstance',out:'TRAINING management event:course-operator changed orders; no reviewed deployment ticket linked',clue:true,note:'Pehle se daala badlav ka saboot operations/change-control ki kami dikhata hai. Asli ikattha hui history nahi.'},{cmd:'aws rds describe-db-instances --db-instance-identifier orders',out:'MultiAZ:false;BackupRetentionPeriod:0;DBInstanceStatus:available',clue:true,note:'Is instance ka available hona bataye HA/history contract ko poora nahi karta, na recovery prove karta hai.'},{cmd:'aws cloudwatch describe-alarms',out:'MetricAlarms:[]',clue:true,note:'Is fixture mein koi diagnostic alarm set nahi. Asli shuru se aakhir tak monitoring ka bhi bada review chahiye.'},{cmd:'cat review.txt',out:'Restore rehearsal blocked by TEST key permission; no accepted-order reconciliation completed',clue:true,note:'Security dependencies aur recovery ki practice overlap karti hain; save hue backup ko safal restore mat kaho.'}],questions:[Q('In chaar incidents se kaunsi report sabse sahi nikalti hai?', 'Recovery aur change/detection ki kamiyan pehle rakho, security dependencies aur owners ke saath; kai pillars overlap karte hain',['Har incident ko sirf Reliability mein daalo aur baaki band karo, kyunki ek hi mukhya label poore workload ko cover kare','Har incident ko sirf Cost mein daalo, kyunki bada budget bina review console badlav apne aap rok deta hai','Available status ke baad review band karo, kyunki woh ek resource field chhe pillars ki saari zaroortein certify karta hai'],0,'Recovery ka risk asli hai, par change control/detection aur key dependencies operations/security ki chintayein bhi jodti hain. Ek label, kharcha badhana ya ek Available field saboot ki saari kamiyan band nahi karte.'),Q('Scanner 3 bataye config findings mein se 0 par pahunchta hai. Improvement plan mein kya likhein?', 'Theek hua config likho, aur restore, delivery aur customer-SLO ke check ka naam wala kaam owners ke saath rakho',['Poore review ki jagah scanner ki ginti rakho, kyunki chune hue zero findings har pillar aur runtime ko certify karte hain','Asli saboot ke objects delete karo, kyunki fail rehearsal ke records naya score bura dikhate hain','Bina restore ke backup recovery poori maano, kyunki 7 din retention naape recovery time ke barabar hai'],1,'Chune config checks apne bataye contracts band kar sakte hain. Poore review/runtime ko phir bhi saboot chahiye; delete karne se seekh chhupti hai aur retention recovery nahi naapta.') ]},
   {type:'terminal',title:'🖥️ Teen bataye config risks theek karo',instructions:'Sirf app ka fixture; koi AWS call nahi. ls/cat review ki policy/alarm/scope dikhate hain. Aaj ke metric periods aur management events di gayi training data hain.',goal:'<p><b>1.</b> Purane orders ka resource/data, private wa-audit bucket/original.txt/BPA, ALB/topic aur pehle se daale events bachao. wa-audit par trail-policy.json lagao; exact shop-review SourceArn/account path aana chahiye.</p><p><b>2.</b> orders ko Multi-AZ aur backup retention 7 din par --apply-immediately ke saath badlo; phir db-instance-available ka wait. Purana instance naye config ke saath available aana chahiye. Asli badlav traffic mein rukawat la sakte hain; yeh model SQL/failover nahi chalata.</p><p><b>3.</b> 5xx-alarm.json se PutMetricAlarm; review-5xx ka poora DescribeAlarms. Diye do Sum counts 8 aur 9 &gt;5 har 60s par, isliye ALARM aana chahiye; yeh healthy customer SLO nahi. Purana topic destination bachao.</p><p><b>4.</b> us-east-1 mein wa-audit ke saath shop-review banao: --is-multi-region-trail, --include-global-service-events aur --enable-log-file-validation. Default model ka selector All management events record karta hai; data events alag hain. StartLogging, phir poora GetTrailStatus. IsLogging:true aana chahiye, sirf config ke roop mein.</p><p>8 actions. Aaj ki state aur aaj ka readback zaroori; delete, public policy, haath ka alarm OK, purana status ya chhoote fixes nahi chalenge. In 3 config risks ka zero hona asli restore, S3 log/digest delivery/validation, metric wala paging ya AWS WA certificate prove nahi karta.</p>',account:seed(),files,tasks,solution,hints:['review.txt, trail-policy.json aur 5xx-alarm.json dekho. Asli cheezein bachao; DB availability, alarm data aur trail permission/logging alag rakho.',solution.slice(0,3).join(' phir '),solution.slice(3,5).join(' phir '),solution.slice(5).join(' phir ')],success:AG.allOf(tasks),successText:'Teen bataye config contracts theek hue, asli saboot/orders bache. Sahi 5xx alarm diye breaches pakadta hai; aaj ke trail logging/management/digest settings padhe gaye. Asli restore, logs/digests + validation, alarm delivery aur customer SLO naam wale runtime kaam rehte hain.'},
   {type:'docker',title:'🐳 Lab21: chune risks ka asli scanner aur kamiyan',project:'21-wellarch-risk-scan',goal:'Apna seed/scan/repair/scan/cleanup sequence chalao aur local asli metadata ko na check hue runtime se alag pehchano.',why:'Moto CloudTrail bucket policy na hone par bhi maan leta hai, delivery status nakli banata hai aur LookupEvents nahi kar sakta. Scanner ko apne contracts aur limits batane chahiye.',steps:[{text:'aws-gurukul se README/lab.py/risk_scan.py padho, phir exact launcher chalao.',cmd:'./docker-labs/21-wellarch-risk-scan/seed.sh',expect:'Repair se pehle ginti 3, teen bataye config repairs ke baad 0. 7 behaviour checks + cleanup = 8; asli TEST saboot wapas mila.'},{text:'Pakdi gayi no-policy, selector, shuru ka alarm aur event-history ki kami wali lines padho.',expect:'Moto ne bina bucket policy logging maan li; shuru ka alarm OK Unchecked; default selectors []; LookupEvents HTTP 500. Bucket mein sirf TEST-preserve.txt hai; na pahunche CloudTrail logs/digests, na asli ALB.'},{text:'Scoped cleanup aur print hua apna endpoint band hona check karo.',expect:'PASS: 8 apne fixture resources saaf; OWNED MOTO STOPPED / LISTENER CLOSED. Saare clients ne apna thodi der ka endpoint use kiya, chahe env.sh ka banner 4566 bataye.'}],observe:Q('Lab21 kis result ko support karti hai?', 'Teen bataye config contracts aur asli TEST bytes check hue; poora review aur production runtime check nahi hue',['0 ki ginti prove karti hai ki har AWS WA sawaal pass hua, kyunki scanner saare chune lenses aur saboot ki jagah le leta hai','IsLogging aur Moto ka LatestDeliveryTime prove karte hain ki S3 digest files pahunchi aur unke signatures check ho chuke','Shuru ka alarm OK prove karta hai ki asli jaisa checkout load pass hua, kyunki local diagnostic alarm safal bana'],2,'Scoped scanner/metadata/bachav ke checks pass hue. Yeh AWS WA Tool nahi; asli pahunche objects/digests, validation aur asli jaisa traffic nahi tha, isliye status/initialOK unhe prove nahi kar sakte.')},
   {type:'quiz',title:'🎓 Faislon ka review, pillar ke naare nahi',questions:[
    Q('Ek team launch se pehle WA review chahti hai. Sabse pehle kya hona chahiye?', 'Workload/business goals, dependencies aur owners tay karo, phir lagu lens ke liye saboot ikattha karo',['Har AWS service se shuru karo aur tab tak products jodo jab tak har pillar ki ek service diagram mein na aa jaaye','Yaad se fixed 50 sawaalon ke jawaab do, kyunki chune lenses aur workload ka scope sawaal nahi badalte','Pehle sabse sasta instance chuno aur saari recovery/security zarooraton ko baad ki sajaawat maano'],0,'Workload ka scope/goals review ka base hain. Services ki ginti, yaad kiye fixed sawaal aur shartein se pehle kharcha sahi business architecture nahi banate.'),
    Q('Reviewer sawaalon ke jawaab ke baad naya WA milestone save karta hai. Seedha kya badla?', 'Tool ne ek time ki review state pakdi; infrastructure ke badlav aur runtime tests abhi bhi chalane hain',['Har risky resource apne aap dobara deploy hua, kyunki milestones improvement plan ko account par laga dete hain','Saare high risks hamesha ke liye delete ho gaye, kyunki naya timestamp purane saboot ki zaroorat khatam kar deta hai','Database backups apne aap restore hue, kyunki milestone banana managed service ka recovery test API hai'],1,'Milestone review ki state, notes/risks ek time par likhta hai. Yeh deploy nahi karta, asli risks delete nahi karta, na restore tests chalata hai; sudhaar/saboot asal mein aane chahiye.'),
    Q('Zaroori serving ko interruption aur ek AZ jaane par bhi 2000 requests/s chahiye. Spot sasta hai. Faisla?', 'Kaafi test kiya non-Spot base rakho; Spot sirf wahan jahan recovery aur zarooratein allow karein',['Saari serving Spot par karo, kyunki chhoot ka percentage hi interruption mein pakki minimum capacity hai','Zaroori traffic ke interruption scenario mein bhi desired Spot instances ko pakka gino','AZ jaane wali zaroorat hata do, kyunki Cost Optimization mein sirf sabse kam ghante ka bill hi niyam hai'],2,'Kharcha shartein ke andar kam kiya jaata hai. Spot interrupt ho sakta hai, desired pakki ready capacity nahi, aur business ki failure wali zaroorat chupchaap hataayi nahi ja sakti.'),
    Q('Backup retention 7 din hai; koi restore rehearsal nahi. Kaunsa daava sahi saabit hota hai?', '7 din ki recovery-history setting hai; asli recovery time/data point aur milaaye app results ke tests chahiye',['RTO 7 minute hai, kyunki backup-retention ka number seedhe pakka restore time maana jaata hai','RPO zero hai, kyunki managed backup config har bahar ki dependency ko DB ke saath ek jhatke mein commit karta hai','Regional DR poora hai, kyunki Multi-AZ standby aur rakhe backups test ki hui regional recovery ke barabar hain'],3,'Retention config/history ki window hai. Yeh RTO/RPO nahi naapta, bahar ki atomicity nahi sambhalta, na regional recovery saabit karta hai; restore/milaan ka saboot abhi bhi chahiye.'),
    Q('Pehle se trail na ho, aur haal ke ek management badlav ki jaanch karni hai. Pehla source?', 'Sahi Region aur 90 din ki window mein CloudTrail Event history; aage ki trail delivery ek alag setup hai',['Naya trail banao aur ummeed karo ki woh har purana data aur management event destination bucket mein backfill karega','Sirf CloudWatch target latency use karo, kyunki component ka percentile har config API ke principal ko pehchanta hai','Digest banana on karo aur maan lo ki feature saare missing purane management-event log objects dobara bana deta hai'],0,'Event history naye trail se alag, haal ke Region-scoped management events deta hai. Trails/digests missing history backfill nahi karte; latency har API principal ko nahi pehchanti.'),
    Q('Trail par log-file validation on hai aur IsLogging:true hai. Kya alag bacha hai?', 'Pahunche log/digest objects check karo aur integrity validation chalao; sirf flags purani files check nahi karte',['Dono flags ko saboot maano ki UpdateTrail ke dauran har purana S3 object apne aap signature-check ho gaya','Bucket permission hata do, kyunki on validation CloudTrail ko har destination path ka chhupa access de deta hai','Poora security review band bolo, kyunki ek logging flag saare identity, threat aur business controls cover karta hai'],1,'Validation on karne se pahunche logs ke liye digest bante hain; validation khud alag hai. Destination ki permission aur bada security review zaroori rehte hain; flags har purana object check nahi karte.'),
    Q('Rate ki chhoot kharcha kam karti hai jabki workers/vCPU/runtime same hain. Sustainability ka result?', 'Resource-hours same reh sakte hain; har kaam ke business output par resources aur mahaul ka asar naapo',['Resources ka use chhoot ke percentage jitna girta hai, kyunki daam ghatne se utna CPU band ho jaata hai','Poore customer orders zaroor badhte hain, kyunki chhota bill behtar kaam ke throughput ke barabar hai','Zaroori resilience agle kadam mein hata do, kyunki resources ki ginti kam karna business ki shartein se pehle aata hai'],2,'Daam aur resources ka use alag hain. Chhoot CPU cycles band nahi karti, na zyada poora kaam prove karti hai; sustainability zaroori business/resilience shartein ke andar hi chalti hai.'),
    Q('Chuna scanner 0 findings batata hai; poore review mein identity aur restore ka saboot abhi bhi nahi. Report?', 'Saaf batao kaun se checks pass hue, baaki risks/tests owners ke saath rakho aur poore framework ka certificate mat bolo',['Har bina jawaab lens sawaal ko poora maano, kyunki kisi bhi scanner ka zero official poori WA Tool rating hai','Shuru ka milestone delete karo, taaki history mein sirf saaf result rahe aur bachi anjaani baatein gayab ho jaayein','Saare recovery risks band karo, kyunki scanner ki ginti asli failover ka time aur accept hue orders ka milaan naapti hai'],3,'Saboot ka scope imaandari se batao. Chuna scanner poora WA Tool assessment nahi, delete karne se progress/seekh chhupti hai, aur field checks runtime recovery/business results nahi naapte.')
   ]}
  ],
  interview:{title:'Interview: review ka saboot aur audit ka repair',instructions:'Chaar faisle, phir asli trail theek karo, saboot badle ya baaki safeguards band kiye bina.',questions:[
   Q('Ek instance benchmark p95 sudhaarta hai par mahine ka kharcha badhata hai. Review ka sabse mazboot jawaab?', 'Naapi performance ki zaroorat, budget aur options compare karo; sahi trade-off aur bacha risk likho',['Har tez option reject karo, kyunki Cost Optimization ko bataye customer needs ke bawajood sabse chhota bill chahiye','Sabse bada instance hamesha ke liye le lo, kyunki ek achha benchmark aage ki saari demand aur dependencies pakki karta hai','Faisle ko sirf Sustainability mein daalo, kyunki mehenga hardware hamesha har performance risk hata deta hai'],0,'Trade-offs zarooraton aur naap se hote hain. Kharcha SLO nahi mita sakta, ek benchmark aage ka behaviour pakka nahi karta, aur sirf daam se mahaul/performance ke results ka label nahi lagta.'),
   Q('Ek custom lens team ki practice ko poora mark karta hai. Reviewer ko kya yaad rakhna chahiye?', 'Custom lenses user ke banaye hain, official AWS content nahi; scope, version, notes aur saboot rakho',['Har custom jawaab AWS certificate hai, kyunki lens publish karna runtime saboot ki zimmedari transfer kar deta hai','Custom lens saare Framework sawaalon ki jagah apne aap le leta hai aur workload ki boundary tay karne ki zaroorat hata deta hai','Lens lagane se saari zaroori recovery drills chal jaati hain, kyunki questionnaire chunna infrastructure test engine bhi hai'],1,'Custom content AWS ke official Lens Catalog se alag hai. Lens lagana/jawaab runtime certify nahi karte, scope ki zaroorat nahi hataate, na infrastructure drills chalate hain.'),
   Q('Ek security finding ka asar bada hai par poora fix mahino lega. Sahi saabit hone wali planning?', 'Zimmedar owners ke saath prioritize karo; beech ke controls, expiry aur bacha risk review karo',['Scanner ki ginti zero hone tak likha hua asar kam karo, kyunki mushkil fix dikhna nahi chahiye','Pichhle milestones delete karo, kyunki purana saboot hatana asli failure ko rokne ke barabar hai','Scope badle bina risk ko NotApplicable mark karo, kyunki mehenga ilaaj backlog par nahi rehna chahiye'],2,'Prioritize karna aur time ki limit wala zimmedar ilaaj bacha risk dikhate hain. Score badalna/saboot delete karna risk chhupata hai; NotApplicable asli scope ko dikhaye, ilaaj ke kharche ya mushkil ko nahi.'),
   Q('Trail ka status purana hai; aakhri safal read ke baad selectors badle. Aaj ki readiness ka saboot kya hai?', 'Aaj ka maksad wala selector/permission/logging state dekho aur taaza status lo; delivery tests alag rakho',['Purana status dobara use karo, kyunki pehle ka IsLogging flag prove karta hai ki baad ka har selector sahi events pakadta hai','Doosre naam ka trail banao aur asli saboot phenk do, kyunki naye naam wale resources purane validation results le lete hain','Sirf LookupEvents chalao, kyunki ek purana event dikhna aaj ki destination permissions aur aage ki digest delivery pakki karta hai'],3,'Aaj ka config/revision aur chalne layak destination maayne rakhte hain; taaza status bhi sirf metadata hai. Purane reads, naya naam ya purana lookup aage ki delivery/validation prove nahi kar sakte.') ,
   {terminal:{type:'terminal',title:'🖥️ Ruka hua asli review trail theek karo',instructions:'Asli trail bana hai; uski pehchaan, saboot aur baaki safeguards rakho.',goal:'<p>shop-review single-Region/global-off/validation-off aur ruka hua hai; selector management events ko bahar rakhta hai. Asli wa-audit policy pehle se review hui hai. Teeno flags update karo, management.json se PutEventSelectors, StartLogging, phir poora GetTrailStatus. Asli trail ki pehchaan, bucket/original.txt, DB HA/backups, alarm/topic/ALB aur pehle se daale events bachao. 4 actions; sirf config ki ummeed, purana backfill ya pahunche digest ka asli validation nahi.</p>',account:seed(true),files,tasks:itasks,solution:isolution,hints:['Asli trail/status/selectors dekho. Flags aur All-management scope theek karo; trail ya saboot mat badlo.',isolution.slice(0,2).join(' phir '),isolution.slice(2).join(' phir ')],success:AG.allOf(itasks),successText:'Asli trail/saboot bache; review kiye flags, All-management selector, logging aur aaj ka status wapas. Asli pahunchi files/digests aur integrity validation alag rehte hain.'}}
  ]},
  success:['Chhe pillars ko business ke risks/saboot aur overlaps se samjha sakta hoon.','Workload/lens, improvement plan, owner aur milestone ko asli review mein use kar sakta hoon.','Config, runtime/customer ka result aur limit wala scanner result alag pehchaan sakta hoon.'],
  homework:'<p>Optional, sirf approved asli-AWS sandbox mein; resources/tests ka bill ho sakta hai. WA Tool mein ek non-sensitive workload define karo aur soch kar lagu official/custom lens chuno. Imaandar notes aur ek prioritized sudhaar/owner/test/rollback ke saath baseline milestone save karo. Alag saaf manzoori ke saath alag restore/milaan, asli component alert delivery aur CloudTrail log/digest validation chalao; production data bachao. Aage ka saboot/milestone save karo. Cleanup: sirf apne test resources; storage, log/data-event, compute aur waiting-period ke charges ka hisaab rakho.</p>',
  cards:[{front:'Six pillars?',back:'Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, Sustainability. Business ke sawaal se shuru karo; controls overlap kar sakte hain.'},{front:'WA review = audit certificate?',back:'Nahi; faislon/saboot ka kaam ka review, improvement plan ke saath. Questionnaire ya local scanner availability/compliance ka certificate nahi.'},{front:'Fixed50questions?',back:'Fixed ginti ka koi vaada nahi. Chuna lens/version aur scope sawaal tay karte hain; official Lens Catalog aur user ke custom lenses alag hain.'},{front:'Milestone runs a deployment?',back:'Nahi. Ek time ki review state. Asli badlav aur check alag se chalane aur saabit karne padte hain.'},{front:'Retention vs RTO/RPO?',back:'Retention rakhi hui recovery history hai. Sahi drill mein asli recovery time/data point naapo aur business/app results milao.'},{front:'CloudTrail history/trail/digest?',back:'Haal ki Region-scoped 90 din ki management history aage ki chuni trail delivery se alag hai. Aage ke digests on karna logs ko check nahi karta.'},{front:'Discount equals sustainability?',back:'Wahi resource-hours kam kharche mein ho sakte hain. Zaroori resilience bachate hue har kaam ke output par resources/mahaul ka asar naapo.'},{front:'Lab21 proves what?',back:'3 bataye config contracts aur TEST ka bachav, 7 behaviour + cleanup = 8. Moto ki permission/delivery/history wali kamiyan; na SQL/traffic/log delivery/digest/runtime, na poora WA assessment.'}]
 }]);
})();
